function GachaponResultViewNew:GetDoubleCorn(pool)
    if checkInt(pool.ifDoubleCorn) > 0  then
        return pool.ifDoubleCorn
    end
    return 0
end
function GachaponResultViewNew:OnInitialize()
    return CoWaitDo(function()
        local param = CfUtils.DialogSafeParameters(self.controller)
        self._tabResult = param.result
        self._jumpIndex = param.jumpIndex
        self._responseData  = param.responseData
        self._activityPoint = param.activityPoint
        --if self._tabResult ~= nil then
        --    printInfo(table.dump(self._tabResult))
        --end
        self._topRare = param.topRare
        self._statistic = param.statistic
        self._pool = param.Pool
        self._callType = param.CallType
        self._isRookieCall = param.isRookieCall

        self._cacheOpen = KCookie.Get("DRAW_CARD_VIEW_STATE")
        if not isNull(self._cacheOpen) then
            printInfo(table.dump(self._cacheOpen))
            KCookie.Set("DRAW_CARD_VIEW_STATE", nil)
        end
        self._isRookieView = KCookie.Get("DRAW_CARD_ROOKIE_VIEW")
        self._finalResultId = checkInt(KCookie.Get("DRAW_CARD_SELECT_FINAL"))
        self._isCardViewBack = checkInt(KCookie.Get("IS_CARD_VIEW_BACK")) == 1
        KCookie.Set("IS_CARD_VIEW_BACK", nil)

        local comp = GachaponUtils.GetGachaponComp()
        if comp.AllGachapon[self._jumpIndex + 1] == nil or comp.AllGachapon[self._jumpIndex + 1].poolId ~= self._pool.poolId then
            self._jumpIndex = 0
        end

        self.selectStashedCB_ = Events.AddListener(Constants.EventNames.GACHAPON_CHECK_CACHE_SELECT_STASHED, function()
            self._finalResultId = GachaponConstants.NewComerKey.CacheResult
            KCookie.Set("DRAW_CARD_SELECT_FINAL", self._finalResultId)
            self._cachedResult = true
            self._isCardViewBack = true
            self:RefreshStage()
            self:ShowResult()
        end)
        self.selectCurrentCB_ = Events.AddListener(Constants.EventNames.GACHAPON_CHECK_CACHE_SELECT_CURRENT, function()
            self._finalResultId = GachaponConstants.NewComerKey.CurrentResult
            KCookie.Set("DRAW_CARD_SELECT_FINAL", self._finalResultId)
            self._cachedResult = true
            self._isCardViewBack = true
            self:RefreshStage()
            self:ShowResult()
        end)

        -- switch parent
        local taskTipsNode = param.taskTipsNode
        if isNotNull(taskTipsNode) then
            taskTipsNode.controller.transform:SetParent(self.controller.transform)
            CfUtils.SetActive(taskTipsNode.controller.transform, true)
        end
    end)
end

function GachaponResultViewNew:OnFinalize()
    return CoWaitDo(function()
        Events.RemoveListener(Constants.EventNames.GACHAPON_CHECK_CACHE_SELECT_STASHED, self.selectStashedCB_)
        Events.RemoveListener(Constants.EventNames.GACHAPON_CHECK_CACHE_SELECT_CURRENT, self.selectCurrentCB_)
        CfUtils.ConditionRemove(GachaponConstants.GachaponBlockKeys.GachaponResultViewExtraRewards)
        CfUtils.ConditionRemove(GachaponConstants.GachaponBlockKeys.GachaponResultViewAnim)
        local defaultCam = UIModule.RootCanvas.defaultCamera
        defaultCam.fieldOfView = self.originField_
        CfUtils.SetUICameraProjection(true)
        GachaponUtils.ResetCameraData(URPCameraController.uiCamera)
        self:HideNavigationBarRoot()
        self:Dispose()
        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end


local rookieScale = 0.9
local tenScale = 1
local cellNam = "GachaCell%s"
function GachaponResultViewNew:UpdateGrid()
    if self._isRookieView then
        self.grid.localScale = Vector3(rookieScale, rookieScale, 1)
    else
        self.grid.localScale = Vector3(1, 1, 1)
    end
end


function GachaponResultViewNew:ShowResult()
    local allData      = self._tabResult
    local gachaponComp = GachaponUtils.GetGachaponComp()
    local rookieCall   = gachaponComp.rookieCall
    local stashedData  = rookieCall[GachaponConstants.NewComerKey.CacheResult]
    local currentData  = rookieCall[GachaponConstants.NewComerKey.CurrentResult]
    if self._isRookieView then
        allData = stashedData
    end
    if self._finalResultId == GachaponConstants.NewComerKey.CacheResult then
        allData = stashedData
    elseif self._finalResultId == GachaponConstants.NewComerKey.CurrentResult then
        allData = currentData
    end

    -- 隐藏抽卡单元格模板
    CfUtils.SetActive(self.GachaCell, false)

    -- 填充抽卡网格容器
    local cnt = #allData
    GachaponUtils.ResizeContent(self.grid, cnt, self.GachaCell)

    -- 添加屏幕遮挡
    CfUtils.ConditionAppend(GachaponConstants.GachaponBlockKeys.GachaponBlockKeys)

    -- 记录翻卡总数
    self._processCnt = cnt

    self:UpdateGrid()

    -- 清空之前的特效
    if self._effectIns ~= nil then
        for i = 1, #self._effectIns do
            CfUtils.SafeDelete(self._effectIns[i])
        end
        self._effectIns = nil
    end

    -- 更新每个结果单元
    for i = 1, cnt do
        local trans = self.grid:GetChild(i - 1)
        if cnt == 10 then
            --十连抽抽动画是GachaCell 1 到10
            trans.localScale = Vector3(tenScale, tenScale, 1)
            trans.name = string.format(cellNam, i)
        else
            --单抽动画是GachaCell
            trans.name = "GachaCell"
        end
        self:UpdateGachaCell(trans, allData[i], i)
        self:AddGachaCellEvent(trans, allData[i], i)
    end

    -- 播放出场动画
    local co = CoStart(function()
        local animName = cnt == 10 and "View_Enter_Cell10" or "View_Enter_Cell1"
        if self._isCardViewBack then
            animName = cnt == 10 and "View_Enter_Cell10_Return" or "View_Enter_Cell1_Return"
        end
        if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) then
            animName = cnt == 10 and "SpecialView_Enter_Cell10" or "SpecialView_Enter_Cell1"
            if self._isCardViewBack then
                animName = cnt == 10 and "SpecialView_Enter_Cell10_Return" or "SpecialView_Enter_Cell1_Return"
            end
        end
        CfUtils.PlayAnimator(self.controller.transform:Find("Container/Root"), animName)

        local gridName = self._isCardViewBack and "Grid_Return" or "Grid_Enter"
        CfUtils.PlayAnimator(self.grid, gridName)

        --新春祈愿
        if self._pool.poolType == GachaponConstants.PoolType.NewYearPray then
            local isSuc = self:IsNewYearPraySuccess()
            if isSuc then
                CfUtils.SetActive(self.controller.transform:Find("Container/Root/ButtonGroup/FontStyleButton2Group"), false)
                local time = (cnt == 10 and 1.667 or 1)
                coroutine.yield(Yielders.GetWaitForSeconds(1.667))
                CfUtils.SetActive(self.GachaponDrawReachDialog, true)
                self.Fruzzy:Capture()
                coroutine.yield(Yielders.GetWaitForSeconds(1.333))
                CfUtils.SetActive(self.GachaponDrawReachDialog, false)
            end
        end

        -- 额外的奖励打脸
        local initParams = CfUtils.DialogSafeParameters(self.controller)
        if initParams.isPopupExtraRewards ~= true then
            local extraRewards = checkTable(self._responseData.extraRewards)
            local luckyBagRewards = checkTable(self._responseData.luckyBagRewards)
            table.insertto(extraRewards, luckyBagRewards)

            -- merge rewards
            local showRewardsMap = {}
            for _, goodsData in ipairs(extraRewards) do
                local goodsId = checkInt(goodsData.goodsId)
                showRewardsMap[goodsId] = showRewardsMap[goodsId] or {goodsId = goodsId, num = 0}
                showRewardsMap[goodsId].num = showRewardsMap[goodsId].num + checkInt(goodsData.num)
            end

            if #extraRewards > 0 then
                local lightDarkCoinRewardNum = checkInt(checkTable(showRewardsMap[Constants.Currency.LightDarkCoin]).num)
                local isOverseaLightDarkType = GachaponUtils.IsOverseaLightDarkType(self._pool.poolType)
                -- 先扣除身上的光暗币，为了配合后面的奖励动画
                if isOverseaLightDarkType and lightDarkCoinRewardNum > 0 then
                    GoodsUtils.ConsumeGoods({
                        {goodsId = Constants.Currency.LightDarkCoin, num = lightDarkCoinRewardNum}
                    }, true)
                end
                CfUtils.ConditionAppend(GachaponConstants.GachaponBlockKeys.GachaponResultViewExtraRewards)
                CoYield(cnt == 10 and 1.2 or 0.4)
                CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = table.values(showRewardsMap), ignoreUICameraProjection = true, cb = function()
                    if isOverseaLightDarkType then
                        GameUtils.StartFlyGoods(self.grid, Constants.Currency.LightDarkCoin, true, function()
                            -- 货币飞入动画播放完毕后，加回来扣除的货币
                            GoodsUtils.DrawRewards({
                                {goodsId = Constants.Currency.LightDarkCoin, num = lightDarkCoinRewardNum}
                            }, true)
                        end)
                    end
                end})
                CfUtils.ConditionRemove(GachaponConstants.GachaponBlockKeys.GachaponResultViewExtraRewards)
            end
            initParams.isPopupExtraRewards = true
        end
    end)
    table.insert(self._loadCo, co)
    
    -- auto open all
    local co = CoStart(function()
        -- if self._isCardViewBack then
            coroutine.yield(Yielders.EndOfFrame)
        -- else
            -- local delay = cnt * GachaponConstants.GachaponResultViewAnim.NodeDelay
            -- local isSingle    = self._callType == GachaponConstants.CallType.One
            -- local play1Delay  = GachaponConstants.GachaponResultViewAnim.PLAY_1_DELAY
            -- local play10Delay = GachaponConstants.GachaponResultViewAnim.PLAY_10_DELAY
            -- local delay       = isSingle and play1Delay or play10Delay  -- 等所有cell出现的动画结束后再打开
            -- coroutine.yield(Yielders.GetWaitForSeconds(delay))
        -- end
        self:AutoOpenAll()
    end)
    
    table.insert(self._loadCo, co)
end

--是否新春祈愿成功了
function GachaponResultViewNew:IsNewYearPraySuccess()
    if self._pool.poolType ~= GachaponConstants.PoolType.NewYearPray then
        return false
    end

    local info = self._pool.activity
    if not info then
        return false
    end

    local data = info.celebrationCardConf[checkString(info.celebrationId)]
    local chooseId = data.roleId

    for k, v in pairs(self._tabResult) do
        local cardId = v.goodsId
        if checkNumber(chooseId) == checkNumber(cardId) then
            return true
        end
    end
    return false
end

