---@param trans UnityEngine.Transform
---@param card table @ { goodsId:string, num:integer, convertGoods:table }
---@param pos integer @ (1-len)
function GachaponResultViewNew:UpdateGachaCell(trans, card, pos)

    -- 更新卡牌信息节点
    ---@param cardId integer
    ---@param cardCell UnityEngine.Transform
    ---@param mainCell UnityEngine.Transform
    local updateCardCell = function(cardId, cardCell, mainCell)
        ---@type CardVo
        local cardVo = cardConfMgr:GetCardByRefId(cardId)

        ---@type CardSkinVo
        local skinVo = cardConfMgr:GetCardSkinBySkinId(cardVo.defaultSkin)

        -- 更新角色卡牌形象
        CfUtils.FillImage(cardCell:Find('Role/charact'), skinVo.cardHeadList)
        
        -- 更新卡牌背景
        local cardRare = cardVo.rare
        CfUtils.SetUISwitchImage(cardCell:Find('ImgBgCard1'), cardRare)
        CfUtils.SetUISwitchImage(cardCell:Find('ImgBgCard2'), cardRare)
        CfUtils.SetUISwitchImage(cardCell:Find('ImgBgCard3'), cardRare)
        CfUtils.SetUISwitchImage(cardCell:Find('ImgBgCard4'), cardRare)
        
        -- card rare
        CfUtils.SetUISwitchImage(cardCell:Find('AnimRoot/Imgtext'), cardRare)
        CfUtils.SetUISwitchImage(cardCell:Find('AnimRoot/Rare/Node/ImgRareIcon'), cardRare)
        CfUtils.SetUISwitchImage(cardCell:Find('AnimRoot/Rare/Node/ImgRareIcon2'), cardRare)
        CfUtils.SetUISwitchImage(cardCell:Find('AnimRoot/Rare/ImgRareBgMask/ImgRareBg'), cardRare)
        CfUtils.SetUISwitchImage(cardCell:Find('AnimRoot/Rare/ImgRareBgMask/ImgRareBg2'), cardRare)
        
        local isSSR = cardRare == Constants.RareType.SSR
        CfUtils.SetActive(cardCell:Find('AnimRoot/Rare/Node/Ssr'), isSSR)
        
        -- card attr
        CfUtils.SetUISwitchImage(cardCell:Find('ProfessionalGroup/ImgType'), cardVo.career)
        CfUtils.SetUISwitchImage(cardCell:Find('ProfessionalGroup/ImgElement'), cardVo.attributeType)

        if not self._isRookieCall then
            local isNew = not isSet(card, "convertGoods")
            CfUtils.SetActive(cardCell:Find('New'), isNew)
            CfUtils.SetActive(mainCell:Find('CardGroup/New'), isNew)  -- GachaponResultViewSpecial.prefab 中的结构
            CfUtils.SetActive(cardCell:Find('Again'), not isNew)
            -- 重复获得时，更新转换信息
            if not isNew then
                local convertGoods = checkTable(card.convertGoods)
                CfUtils.FillText(cardCell:Find('Again/TxtNum'), string.format("x%d", checkInt(convertGoods.num)))
                local imgNode = cardCell:Find('Again/ImgIcon').gameObject:GetComponent(typeof(ImageComp))
                GachaponUtils.LoadSpriteAsync(imgNode, goodsConfMgr:GetPhotoPathById(convertGoods.goodsId))
            end
        end
        
        --dotween anim
        local rareTip  = GachaponConstants.RareTips[cardVo.rare]
        local idlePath = string.format(GachaponConstants.UIEffectCardIdlePath, rareTip)
        local openPath = string.format(GachaponConstants.UIEffectCardOpenPath, rareTip)
        GachaponShared:LoadModel(idlePath)
        GachaponShared:LoadModel(openPath)
        while not GachaponShared:GetModel(idlePath) or not GachaponShared:GetModel(openPath) do
            CoYield()
        end
        self._loadedObjects[idlePath] = true
        self._loadedObjects[openPath] = true

        local particleRoot = cardCell:Find("ParticleRoot")
        CfUtils.SetActive(particleRoot, true)
        if self._effectIns == nil then
            self._effectIns = {}
        end

        local idleIns = GachaponShared:GetModel(idlePath)
        if not isNull(idleIns) then
            idleIns = CfUtils.InstantiateGo(idleIns, particleRoot, false)
            idleIns.name = "idle"
            table.insert(self._effectIns, idleIns)
        end
        
        local openIns = GachaponShared:GetModel(openPath)
        if not isNull(openIns) then
            openIns = CfUtils.InstantiateGo(openIns, particleRoot, false)
            openIns.name = "open"
            table.insert(self._effectIns, openIns)
        end

        coroutine.yield(Yielders.EndOfFrame)
        local effectOpen = particleRoot:Find("open")
        if not isNull(effectOpen) then
            CfUtils.SetActive(effectOpen, true)
        end
        local idleOpen = particleRoot:Find("idle")
        if not isNull(idleOpen) then
            CfUtils.SetActive(idleOpen, true)
        end
    end

    -- 更新道具信息节点
    ---@param goodsId integer
    ---@param goodsCell UnityEngine.Transform
    ---@param mainCell UnityEngine.Transform
    local updateGoodsCell = function(goodsId, goodsCell, mainCell)
        CfUtils.FillText(goodsCell:Find('TxtNum'), string.fmt('x%1', checkInt(card.num)))
        CfUtils.FillText(goodsCell:Find('TextName'), goodsConfMgr:GetGoodsNameById(goodsId))
        CfUtils.FillImage(goodsCell:Find('ImgIcon'), goodsConfMgr:GetPhotoPathById(goodsId))
    end

    -- 更新道具信息节点
    ---@param extraGoods table
    ---@param scoreCell UnityEngine.Transform
    ---@param mainCell UnityEngine.Transform
    local updateScoreCell = function(extraGoods, scoreCell, mainCell)
        local goodsId  = checkInt(extraGoods.goodsId)
        local goodsNum = checkInt(extraGoods.num)
        CfUtils.FillText(scoreCell:Find('TextNumber'), string.fmt('x%1', goodsNum))
        CfUtils.FillImage(scoreCell:Find('ImgIcon'), goodsConfMgr:GetPhotoPathById(goodsId))
    end

    local co = CoStart(function()
        local cardId    = card.goodsId
        local mainCell  = trans:Find('CellMain')
        local cardCell  = mainCell:Find('CardGroup/Card')
        local goodsCell = mainCell:Find('CardGroup/Props')
        local scoreCell = mainCell:Find('CardGroup/Score')
        
        local isCardGoods = GachaponUtils.IsCardGoods(cardId)
        CfUtils.SetActive(cardCell, isCardGoods)
        CfUtils.SetActive(goodsCell, not isCardGoods)

        if isCardGoods then
            updateCardCell(cardId, cardCell, mainCell)
        else
            updateGoodsCell(cardId, goodsCell, mainCell)
        end

        if GachaponUtils.IsOverseaLightDarkType(self._pool.poolType) then
            local extraRewards = checkTable(self._responseData.extraRewards)
            updateScoreCell(extraRewards[pos] or {}, scoreCell, mainCell)
        end
        
        if self._isCardViewBack then
            coroutine.yield(Yielders.EndOfFrame)
        else
            local isSingle    = self._callType == GachaponConstants.CallType.One
            local play1Delay  = GachaponConstants.GachaponResultViewAnim.PLAY_1_DELAY
            local play10Delay = GachaponConstants.GachaponResultViewAnim.PLAY_10_DELAY
            local delay       = isSingle and play1Delay or play10Delay  -- 等所有cell出现的动画结束后再打开
            coroutine.yield(Yielders.GetWaitForSeconds(delay))
        end
        

        self._processCnt = self._processCnt - 1
        if self._processCnt < 1 then
            CfUtils.ConditionRemove(GachaponConstants.GachaponBlockKeys.GachaponBlockKeys)
            -- if  self._pool.poolType == GachaponConstants.PoolType.PointNum and (not self._isCardViewBack) then
            --     local getGachaponConf = GachaponUtils.GetGachaponById(self._pool.poolId)
            --     --- 更新活动点数
            --     local rewards =  {
            --         [1] = {
            --             num = checkInt(self._activityPoint),
            --             goodsId = getGachaponConf.singleCoin,
            --         }
            --     }
            --     CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, { rewards = rewards })
            -- end
            --CfUtils.SetActive(self.BtnTipsGroup, true)
            --CfUtils.SetActive(self.FontStyleButton1.transform.parent, true)
        end
    end)

    if self._loadCo == nil then
        self._loadCo = {}
    end
    table.insert(self._loadCo, co)
end

---@param trans UnityEngine.Transform
---@param card table @ { goodsId:string, num:integer }
---@param pos integer @ (1-len)
function GachaponResultViewNew:AddGachaCellEvent(trans, card, pos)
    local cardId = card.goodsId
    -- local cardVo = cardConfMgr:GetCardByRefId(cardId)
    local mainCell = trans:Find("CellMain")

    SetButtonAction(mainCell, function()
        if GachaponUtils.IsCardGoods(cardId) then
            local co = CoStart(function()
                KCookie.Set("DRAW_CARD_VIEW_STATE", self._cacheOpen)
                KCookie.Set("IS_CARD_VIEW_BACK", 1)
                GachaponUtils.OpenDetail(cardId, nil, {isHideHomeBtn = true})
            end)
            table.insert(self._loadCo, co)
        else
            local goodsVo = goodsConfMgr:GetGoodsVoById(cardId)
            GameUtils.ShowCommonTipsBoard(mainCell, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end
    end)
end

