function GachaponResultViewNew:SetUIState(st)
    local pos = self.controller.transform.localPosition
    local y = st and 0 or 5000
    pos.y = y
    self.controller.transform.localPosition = pos
end


-- runing on self._isRookieView
function GachaponResultViewNew:RefreshStage()
    local gachaponComp = GachaponUtils.GetGachaponComp()
    local rookieCall = gachaponComp.rookieCall
    
    local cntCount = checkInt(rookieCall[GachaponConstants.NewComerKey.CurrentCount])
    local maxCount = checkInt(rookieCall[GachaponConstants.NewComerKey.MaxCount])
    local isDone   = cntCount == maxCount
    --local hasPrev  = isSet(rookieCall, GachaponConstants.NewComerKey.CacheResult)
    --local btnText  = hasPrev and (self._isRookieView and localize("替换暂存") or localize("查看暂存")) or localize("暂存")
    --if isDone then
    --    btnText = (hasPrev and self._finalResultId == 0) and localize("查看暂存") or localize("确定")
    --end
    if isDone then
        CfUtils.FillText(self.FontStyleButton1.transform:Find("Text"), localize("10选1"))
        CfUtils.SetActive(self.FontStyleButton1, true)
    else
        CfUtils.SetActive(self.FontStyleButton1, false)
    end

    if self.Storage then
        CfUtils.SetActive(self.Storage.transform.parent, true)
        CfUtils.SetActive(self.Storage.transform.parent.transform:Find("Txtresults"), false)
        CfUtils.SetActive(self.Storage, not self._isRookieView and not isDone)  -- 新手抽卡剩余次数
    end
    CfUtils.SetActive(self.RoundsGroup, not self._isRookieView)  -- 新手抽卡第几回
    CfUtils.SetActive(self.FontStyleButton2, not self._isRookieView and not isDone)  -- 再抽按钮

    local SaveRoundNum = function()
        CfUtils.WriteLocalData(Constants.PlayerPrefsType.GachaponSaveRoundNum, cntCount)
    end
    local LoadRoundNum = function()
        return checkInt(CfUtils.GetLocalData(Constants.PlayerPrefsType.GachaponSaveRoundNum))
    end

    if self._isRookieView then
        self:ShowNavigationBarRoot()

        if LoadRoundNum() > 0 then
            local roundNumText = localize("以上为第_num_轮召唤结果", { _num_ = LoadRoundNum()})
            CfUtils.FillText(self.Storage.transform.parent.transform:Find("Txtresults"), roundNumText)
            CfUtils.SetActive(self.Storage.transform.parent.transform:Find("Txtresults"), true)
        end
    end
    SetButtonAction(self.FontStyleButton1, function()
        CfUtils.DialogClose(self.controller)
        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
            if dialog.Argument.id ~= self.controller.Argument.id   then
                table.insert(t, dialog.Argument)
            end
        end
        CfUtils.DialogOpen(Constants.UITypeIds.GachaponNumberOfRoundsDialog, {
            isBack = false,
            pool = self._pool
        }, t)
    end)
end

function GachaponResultViewNew:IsAllOpen()
    return #self._tabResult == table.count(self._cacheOpen)
end

function GachaponResultViewNew:AutoOpenAll()
    self.isAutoOpenAll_ = true
    for i = 1, #self._tabResult do
        self:OpenCardCell(i)
    end
    CriWareUtils.PlaySeById(GachaponConstants.GachaponSE.ManualDisappear)
end

---@param pos integer
---@return boolean
function GachaponResultViewNew:CheckOpen(pos)
    if isNull(self._cacheOpen) then
        return false
    end

    return isSet(self._cacheOpen, pos)
end

---@param pos integer
function GachaponResultViewNew:SetOpen(pos)
    if isNull(self._cacheOpen) then
        self._cacheOpen = {}
    end

    self._cacheOpen[pos] = 1
end

function GachaponResultViewNew.SetOneOfGroupActive(parent, name)
    for i = 1, parent.childCount do
        CfUtils.SetActive(parent:GetChild(i - 1), false)
    end
    CfUtils.SetActive(parent:Find(name), true)
end

function GachaponResultViewNew:Dispose()
    if self._loadCo ~= nil then
        for i = 1, #self._loadCo do
            CoStop(self._loadCo[i])
            self._loadCo[i] = nil
        end
        self._loadCo = nil
    end

    if self._effectIns ~= nil then
        for i = 1, #self._effectIns do
            CfUtils.SafeDelete(self._effectIns[i])
        end
        self._effectIns = nil
    end
    
    for objPath, _ in pairs(self._loadedObjects or {}) do
        GachaponShared:DisposeSingle(objPath)
    end
end

function GachaponResultViewNew:ToClose()
    if self._effectIns ~= nil then
        for i = 1, #self._effectIns do
            CfUtils.SetActive(self._effectIns[i], false)
        end
    end

    GachaponShared.TabResult = nil
    GachaponShared.PopUp = nil
    KCookie.Set("DRAW_CARD_POOL_INDEX", checkNumber(self._jumpIndex))
    --todo: 临时改动 测试ResultViewNew
    local comp = GachaponUtils.GetGachaponComp()
    -- 如果在新手中 ， 直接
    if comp:IsRookieCallStarted() then
        UIModule.BackArgumentDialog()
    else
        return CoStart(function()
            local wait = true
            GameUtils.Request(Interfaces.CallHome, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    wait = response
                end
            end)
            while wait == true do
                coroutine.yield()
            end
            comp:InitialGachapon(wait.data)
            UIModule.BackArgumentDialog()
        end)
    end

    -- self.controller:Close()
end

function GachaponResultViewNew:ShowNavigationBarRoot()
    CfUtils.SetTopCommonActive(true)
    CfUtils.SetTopCommonCb(function()
        Events.Broadcast(Constants.EventNames.SHARE_BUTTON_REFRESH)
        self._isRookieView = false
        KCookie.Set("DRAW_CARD_ROOKIE_VIEW", self._isRookieView)
        self:RefreshStage()
        self:ShowResult()
        self:HideNavigationBarRoot()
    end)
end

function GachaponResultViewNew:HideNavigationBarRoot()
    CfUtils.SetTopCommonActive(false)
    CfUtils.ResetNavigatorCustomBackAction()
end

return GachaponResultViewNew
